-- OLD and NEW are record variables: assigning a row of another structure
-- gives them that structure, and only a row trigger's returned record must
-- match the triggering table.
CREATE TABLE t254 (a int, b text);
CREATE FUNCTION f254() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
  NEW := ROW(1, 'x'::text, 3);
  RAISE NOTICE 'new % f1 % f3 %', NEW, NEW.f1, NEW.f3;
  BEGIN RAISE NOTICE 'a %', NEW.a; EXCEPTION WHEN OTHERS THEN RAISE NOTICE '% %', SQLSTATE, SQLERRM; END;
  NEW.f3 := 30;
  RAISE NOTICE 'after field %', NEW;
  NEW := ROW(5, 'y'::text);
  RAISE NOTICE 'second %', NEW;
  RETURN NEW;
END $$;
CREATE TRIGGER b254 BEFORE INSERT ON t254 FOR EACH ROW EXECUTE FUNCTION f254();
INSERT INTO t254 VALUES (0, 'z') RETURNING *;
CREATE OR REPLACE FUNCTION f254() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN NEW := ROW(1, 'x'::text, 3); RETURN NEW; END $$;
INSERT INTO t254 VALUES (0, 'z');
CREATE OR REPLACE FUNCTION f254() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN NEW := ROW(1, 2); RETURN NEW; END $$;
INSERT INTO t254 VALUES (0, 'z');
CREATE OR REPLACE FUNCTION f254() RETURNS trigger LANGUAGE plpgsql AS $$
DECLARE r record;
BEGIN
  SELECT 7 AS q, 'w'::text AS p INTO r;
  NEW := r;
  RAISE NOTICE '% %', NEW.q, NEW.p;
  NEW.q := 8;
  RAISE NOTICE '%', NEW;
  RETURN NEW;
END $$;
INSERT INTO t254 VALUES (0, 'z') RETURNING *;
CREATE OR REPLACE FUNCTION f254() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN NEW := ROW(1, 'x'::text, 3); RETURN NULL; END $$;
INSERT INTO t254 VALUES (0, 'z');
CREATE OR REPLACE FUNCTION f254() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN NEW := NULL; RAISE NOTICE 'null %', NEW; NEW.a := 1; RETURN NEW; END $$;
INSERT INTO t254 VALUES (9, 'q');
CREATE OR REPLACE FUNCTION f254() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN NEW := NULL; RETURN NEW; END $$;
INSERT INTO t254 VALUES (9, 'q');
CREATE OR REPLACE FUNCTION f254() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN NEW := ROW(1, 'x'::text, 3); NEW.a := 1; RETURN NEW; END $$;
INSERT INTO t254 VALUES (9, 'q');
CREATE OR REPLACE FUNCTION f254() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN NEW := (SELECT t FROM t254 t ORDER BY a LIMIT 1); NEW.b := NEW.b || '!'; RETURN NEW; END $$;
INSERT INTO t254 VALUES (9, 'q') RETURNING *;
DROP TRIGGER b254 ON t254;
-- An AFTER row trigger's result is checked too; a statement trigger's is not.
CREATE FUNCTION g254() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN NEW := ROW(1, 'x'::text, 3); OLD := NEW; RAISE NOTICE 'old %', OLD; RETURN NEW; END $$;
CREATE TRIGGER a254 AFTER INSERT ON t254 FOR EACH ROW EXECUTE FUNCTION g254();
INSERT INTO t254 VALUES (10, 'after');
DROP TRIGGER a254 ON t254;
CREATE TRIGGER s254 AFTER INSERT ON t254 FOR EACH STATEMENT EXECUTE FUNCTION g254();
INSERT INTO t254 VALUES (11, 'statement');
DROP TRIGGER s254 ON t254;
CREATE FUNCTION h254() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN RETURN ROW(1, 2, 3); END $$;
CREATE TRIGGER a254 AFTER UPDATE ON t254 FOR EACH ROW EXECUTE FUNCTION h254();
UPDATE t254 SET b = b WHERE a = 11;
DROP TRIGGER a254 ON t254;
-- A DELETE trigger's NEW starts NULL with the table's structure.
CREATE FUNCTION d254() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN NEW.a := 1; RAISE NOTICE 'new %', NEW; NEW := ROW('k'::text); RAISE NOTICE '%', NEW.f1; RETURN OLD; END $$;
CREATE TRIGGER d254 BEFORE DELETE ON t254 FOR EACH ROW EXECUTE FUNCTION d254();
DELETE FROM t254 WHERE a = 11;
SELECT * FROM t254 ORDER BY a, b;
